content.title:
cd "/Users/eilonxtxue/Documents/obsidian/obsidian_bk/AIReadPaper/20-Surveys/World-Models" && python3 - <<'EOF'
s=open("视觉世界模型 - Survey.md").read().split('\n')
bad=0
for i,l in enumerate(s):
    if l.startswith('|') and i>0 and not s[i-1].startswith('|') and s[i-1].strip():
        print(f'NO BLANK LINE before table at {i+1}: prev={s[i-1][:60]!r}'); bad+=1
print('table spacing issues:',bad)
print('total lines:',len(s))
# heading order
import re
for i,l in enumerate(s):
    if re.match(r'^#{2,3} ',l): print(f'{i+1:4d} {l[:70]}')
EOF

